            ProductionSetupBlockReason.CameraCalibrationDistortionMismatch =>
                "\u5f53\u524d9\u70b9XY\u6807\u5b9a\u5df2\u5931\u6548\uff1a\u955c\u5934\u7578\u53d8\u6807\u5b9a\u5df2\u53d8\u5316\u3002\u8bf7\u91cd\u65b0\u5b8c\u62109\u70b9XY\u6807\u5b9a\u3002",
            ProductionSetupBlockReason.RAxisCenterMissing =>
                "\u5f53\u524d\u672a\u5b8c\u6210\u6709\u6548R\u8f74\u4e2d\u5fc3\u6807\u5b9a\uff0c\u65e0\u6cd5\u8fdb\u884c\u5de5\u5382\u7ea7XYR\u8865\u507f\u3002\u8bf7\u8fdb\u5165 \u76f8\u673a\u8bbe\u7f6e -> \u6807\u5b9a\u7ba1\u7406\uff0c\u5b8c\u6210R\u8f74\u4e2d\u5fc3\u6807\u5b9a\u3002",
            ProductionSetupBlockReason.RAxisCenterCameraMismatch =>
                "\u5f53\u524dR\u8f74\u4e2d\u5fc3\u6807\u5b9a\u5df2\u5931\u6548\uff1aR\u8f74\u4e2d\u5fc3\u6807\u5b9a\u4f7f\u7528\u76849\u70b9XY\u6807\u5b9a\u4e0e\u5f53\u524d\u673a\u5668\u6807\u5b9a\u4e0d\u4e00\u81f4\u3002\u8bf7\u91cd\u65b0\u5b8c\u6210R\u8f74\u4e2d\u5fc3\u6807\u5b9a\u3002",
            ProductionSetupBlockReason.TemplateImageMissing =>
                "\u5f53\u524d\u6807\u51c6\u4f4d/\u6a21\u677f\u7684\u6a21\u677f\u539f\u56fe\u5df2\u4e22\u5931\uff0c\u53ea\u5269\u6807\u51c6\u4f4d\u6570\u636e\uff0c\u65e0\u6cd5\u53ef\u9760\u5224\u65ad\u89d2\u5ea6\u3002\u8bf7\u91cd\u65b0\u5efa\u7acb\u5f53\u524d\u578b\u53f7\u6807\u51c6\u4f4d/\u6a21\u677f\u3002",
            ProductionSetupBlockReason.TemplateCameraCalibrationMissing =>
                "\u5f53\u524d\u6807\u51c6\u4f4d/\u6a21\u677f\u7f3a\u5c119\u70b9XY\u6807\u5b9a\u6765\u6e90\u3002\u8bf7\u91cd\u65b0\u5efa\u7acb\u5f53\u524d\u578b\u53f7\u6807\u51c6\u4f4d/\u6a21\u677f\u3002",
            ProductionSetupBlockReason.TemplateCameraCalibrationMismatch =>
                "\u5f53\u524d\u6807\u51c6\u4f4d/\u6a21\u677f\u5df2\u5931\u6548\uff1a\u5efa\u7acb\u6807\u51c6\u4f4d/\u6a21\u677f\u65f6\u4f7f\u7528\u76849\u70b9XY\u6807\u5b9a\u4e0e\u5f53\u524d\u673a\u5668\u6807\u5b9a\u4e0d\u4e00\u81f4\u3002\u8bf7\u91cd\u65b0\u5efa\u7acb\u5f53\u524d\u578b\u53f7\u6807\u51c6\u4f4d/\u6a21\u677f\u3002",
            ProductionSetupBlockReason.TemplateDistortionCalibrationMismatch =>
                "\u5f53\u524d\u6807\u51c6\u4f4d/\u6a21\u677f\u5df2\u5931\u6548\uff1a\u5efa\u7acb\u6807\u51c6\u4f4d/\u6a21\u677f\u65f6\u4f7f\u7528\u7684\u7578\u53d8\u6807\u5b9a\u4e0e\u5f53\u524d\u673a\u5668\u6807\u5b9a\u4e0d\u4e00\u81f4\u3002\u8bf7\u91cd\u65b0\u5efa\u7acb\u5f53\u524d\u578b\u53f7\u6807\u51c6\u4f4d/\u6a21\u677f\u3002",
            _ => "\u5f53\u524d\u751f\u4ea7\u914d\u7f6e\u672a\u5c31\u7eea\uff0c\u8bf7\u68c0\u67e5\u673a\u5668\u6807\u5b9a\u548c\u5f53\u524d\u578b\u53f7\u6807\u51c6\u4f4d/\u6a21\u677f\u3002"
        };
